-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Análise de Dados Aplicada à Gestão' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Prova Prática', 'PENDENTE', v_aula, 'Atividade — Prova Prática (10 questões discursivas)',
      '/MATERIAIS/GESTAO_E_CONTROLE_MATERIAIS/ANALISE_DADOS_APLICADA_GESTAO/ATIVIDADES/PROVA-PRATICA.html', 10, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga se as grandezas "rolos" e "dias" são diretamente ou inversamente proporcionais e monte a regra de três.', 0.3, 'Diretamente proporcionais (mais dias de consumo, mais rolos). Montagem: 900 rolos — 6 dias; x rolos — 30 dias (900/6 = x/30).', 'Palavras-chave: diretamente proporcional; 900 — 6; x — 30. Nota cheia: classifica como direta e monta a proporção. Metade: só uma das duas partes. Zero: classifica como inversa.'),
      (v_atividade, 1, 2, 'Calcule quantos rolos serão consumidos em 30 dias, mostrando a conta.', 0.3, 'x = 900 × 30 ÷ 6 = 4.500 rolos (ou 150 rolos por dia × 30 dias = 4.500 rolos).', 'Palavras-chave: 900 × 30 ÷ 6; 150 por dia; 4.500 rolos. Nota cheia: conta e resultado 4.500. Metade: conta certa com erro de cálculo. Zero: resultado sem conta coerente.'),
      (v_atividade, 1, 3, 'Calcule quantas caixas devem ser compradas e explique o que fazer quando a divisão não dá um número exato.', 0.4, '4.500 ÷ 40 = 112,5 caixas → comprar 113 caixas. Quando a divisão não é exata, arredonda-se para cima, porque não se compra meia caixa e o arredondamento para baixo deixaria faltar material.', 'Palavras-chave: 4.500 ÷ 40; 112,5; arredondar para cima; 113 caixas; não existe meia caixa. Nota cheia: 113 caixas com a justificativa do arredondamento para cima. Metade: 112,5 sem arredondar, ou 113 sem justificar. Zero: 112 caixas ou conta errada.'),
      (v_atividade, 2, 1, 'Calcule a área útil do galpão (descontando o corredor) e a área de um palete, com as unidades.', 0.3, 'Área útil = 20 m × (12 m − 2 m) = 20 × 10 = 200 m². Área do palete = 1,2 m × 1,0 m = 1,2 m².', 'Palavras-chave: descontar o corredor; 200 m²; 1,2 m²; comprimento × largura. Nota cheia: as duas áreas com unidade. Metade: uma área certa, ou as duas sem descontar o corredor (240 m²). Zero: sem conta coerente.'),
      (v_atividade, 2, 2, 'Calcule quantos paletes cabem por nível pelo arranjo (quantos no comprimento e quantas fileiras de cada lado do corredor).', 0.3, 'Comprimento: 20 ÷ 1,2 = 16,67 → 16 paletes. Cada lado do corredor tem (12 − 2) ÷ 2 = 5 m → 5 ÷ 1,0 = 5 fileiras. Total: 16 × 5 × 2 lados = 160 paletes por nível.', 'Palavras-chave: 16 no comprimento; 5 m de cada lado; 5 fileiras; 2 lados; 160 paletes. Nota cheia: 160 com o arranjo mostrado. Metade: arranjo certo com erro de conta, ou esquece um dos lados (80). Zero: só divisão de áreas (166) sem arranjo.'),
      (v_atividade, 2, 3, 'Calcule o peso de um palete carregado, diga se ele respeita o limite e explique por que o número de paletes deve ser conferido pelo arranjo e não só pela divisão das áreas.', 0.4, 'Peso = 50 caixas × 15 kg = 750 kg, abaixo do limite de 1.000 kg, então respeita o limite. Pela divisão das áreas daria 200 ÷ 1,2 ≈ 166 paletes, mas a sobra de espaço (0,8 m no comprimento) não vira palete; por isso o número real é o do arranjo (160).', 'Palavras-chave: 750 kg; abaixo de 1.000 kg; sobra de espaço não vira palete; arranjo; 166 × 160. Nota cheia: peso certo com conclusão e a explicação do arranjo. Metade: só o peso ou só a explicação. Zero: nenhum dos dois.'),
      (v_atividade, 3, 1, 'Calcule o preço do par de luvas depois do aumento de 15%, usando o fator multiplicativo.', 0.3, 'Fator de aumento 1,15 → R$ 80,00 × 1,15 = R$ 92,00.', 'Palavras-chave: fator 1,15; R$ 92,00. Nota cheia: fator e resultado. Metade: resultado certo por outro caminho (80 + 12). Zero: valor errado.'),
      (v_atividade, 3, 2, 'Calcule o preço final com o desconto de 4% à vista, usando o fator multiplicativo.', 0.3, 'Fator de desconto 0,96 → R$ 92,00 × 0,96 = R$ 88,32.', 'Palavras-chave: fator 0,96; aplicar sobre R$ 92,00; R$ 88,32. Nota cheia: fator e R$ 88,32. Metade: desconto aplicado sobre R$ 80,00 ou erro pequeno de conta. Zero: valor sem relação com o caso.'),
      (v_atividade, 3, 3, 'Calcule a variação real do preço em porcentagem e explique por que o colega errou.', 0.4, 'Fator total 1,15 × 0,96 = 1,104 → aumento real de 10,4% (ou 88,32 ÷ 80 − 1 = 0,104). O colega errou porque percentuais sucessivos se multiplicam como fatores (o desconto incide sobre o preço já aumentado), não se somam nem se subtraem.', 'Palavras-chave: 1,15 × 0,96; 1,104; 10,4%; percentuais sucessivos se multiplicam; não se somam. Nota cheia: 10,4% e a explicação da multiplicação dos fatores. Metade: só o 10,4% ou só a explicação. Zero: concorda com os 11%.'),
      (v_atividade, 4, 1, 'Calcule a média das saídas, mostrando a soma e a divisão.', 0.3, 'Soma = 20 + 22 + 22 + 25 + 26 + 105 = 220; média = 220 ÷ 6 ≈ 36,67 caixas por dia.', 'Palavras-chave: soma 220; dividir por 6; 36,67 caixas. Nota cheia: soma, divisão e resultado. Metade: conta certa com erro pequeno. Zero: sem conta coerente.'),
      (v_atividade, 4, 2, 'Calcule a mediana (mostrando o rol em ordem) e diga qual é a moda.', 0.3, 'Rol: 20, 22, 22, 25, 26, 105. Como são 6 valores (par), a mediana é a média dos dois centrais: (22 + 25) ÷ 2 = 23,5 caixas. Moda = 22 caixas (aparece duas vezes).', 'Palavras-chave: rol em ordem; quantidade par; média dos dois centrais; 23,5; moda 22. Nota cheia: mediana 23,5 e moda 22. Metade: só uma das duas certa. Zero: nenhuma.'),
      (v_atividade, 4, 3, 'Diga qual medida representa melhor o consumo típico do almoxarifado e justifique usando o dia atípico.', 0.4, 'A mediana (23,5) representa melhor o consumo típico. O dia atípico de 105 caixas (parada de manutenção) puxa a média para cima (36,67), e comprar pela média geraria excesso de estoque; a mediana é resistente a valores extremos.', 'Palavras-chave: mediana; valor atípico (extremo, outlier); puxa a média; resistente; excesso de compra. Nota cheia: escolhe a mediana e justifica pelo valor atípico. Metade: escolhe a mediana sem justificar bem. Zero: escolhe a média.'),
      (v_atividade, 5, 1, 'Explique o que o desvio padrão mede e por que olhar só a média esconde um risco.', 0.3, 'O desvio padrão mede a dispersão (o quanto os prazos se afastam da média), ou seja, a previsibilidade do fornecedor. Dois fornecedores podem ter a mesma média de 6 dias e um deles variar muito; olhando só a média, o risco de atraso fica escondido.', 'Palavras-chave: dispersão; afastamento da média; previsibilidade; risco escondido pela média. Nota cheia: define dispersão e explica o risco da média. Metade: só uma das partes. Zero: confunde com a média.'),
      (v_atividade, 5, 2, 'Diga qual fornecedor tem o maior desvio padrão, justificando com os prazos (ou com a conta dos desvios).', 0.3, 'O Fornecedor B tem o maior desvio padrão: os prazos vão de 2 a 10 dias, longe da média de 6. Conta: A — desvios² 1, 0, 1, 0, 0 (soma 2; variância 0,4; DP ≈ 0,63 dia); B — desvios² 16, 16, 0, 9, 9 (soma 50; variância 10; DP ≈ 3,16 dias).', 'Palavras-chave: Fornecedor B; amplitude 2 a 10; DP ≈ 3,16 × ≈ 0,63; variância. Nota cheia: B com justificativa pelos prazos ou pela conta. Metade: B sem justificativa. Zero: A.'),
      (v_atividade, 5, 3, 'Diga qual fornecedor você escolheria e o que acontece com o estoque de segurança se a empresa ficar com o fornecedor mais imprevisível.', 0.4, 'Escolher o Fornecedor A, que é previsível (entrega entre 5 e 7 dias). Com o Fornecedor B, a empresa precisa de um estoque de segurança maior para não faltar material nos atrasos, o que aumenta o custo de estoque.', 'Palavras-chave: Fornecedor A; previsível; estoque de segurança maior; risco de falta (ruptura); custo. Nota cheia: escolhe A e explica o estoque de segurança maior com B. Metade: só uma das partes. Zero: escolhe B sem justificativa coerente.'),
      (v_atividade, 6, 1, 'Escreva as fórmulas do Saldo (E2) e do Custo em Estoque (H2).', 0.3, 'Saldo: =C2-D2. Custo em Estoque: =E2*G2.', 'Palavras-chave: =C2-D2; =E2*G2; sinal de igual. Nota cheia: as duas fórmulas. Metade: uma fórmula certa. Zero: nenhuma (ou sem o sinal de igual).'),
      (v_atividade, 6, 2, 'Escreva a fórmula da Armazenagem (I2) usando a taxa de L1 e explique o que aconteceria ao arrastar a fórmula se L1 não estivesse travada com cifrão ($).', 0.3, '=H2*$L$1. Sem o cifrão, a referência é relativa e "anda" ao arrastar (L2, L3...), que estão vazias; o resultado vira zero. O $ (referência absoluta, atalho F4) trava a célula da taxa.', 'Palavras-chave: =H2*$L$1; referência absoluta; cifrão trava; sem $ a referência anda; resultado zero; F4. Nota cheia: fórmula com $L$1 e explicação. Metade: fórmula certa sem explicar, ou explicação sem a fórmula. Zero: fórmula sem $ e sem explicação.'),
      (v_atividade, 6, 3, 'Escreva a fórmula da Situação (J2) com a função SE, mostrando "Repor" quando o saldo for menor que o mínimo e "OK" no outro caso, e a fórmula do custo total em estoque das linhas 2 a 11.', 0.4, '=SE(E2<F2;"Repor";"OK"). Custo total: =SOMA(H2:H11).', 'Palavras-chave: SE; teste lógico E2<F2; textos entre aspas; ponto e vírgula; =SOMA(H2:H11). Nota cheia: as duas fórmulas certas. Metade: só uma, ou SE com erro pequeno (aspas, separador). Zero: nenhuma.'),
      (v_atividade, 7, 1, 'Descreva a regra de formatação condicional (com a fórmula) que pinta de vermelho o saldo abaixo do mínimo e explique por que o $ fica só na coluna.', 0.3, 'Selecionar E2:E200 → Página Inicial → Formatação Condicional → Nova Regra → Usar uma fórmula: =$E2<$F2 → preenchimento vermelho. O $ só na coluna trava as colunas E e F e deixa a linha "andar", para cada item ser comparado com o próprio mínimo.', 'Palavras-chave: formatação condicional; nova regra por fórmula; =$E2<$F2; vermelho; $ na coluna; linha anda; próprio mínimo. Nota cheia: regra com fórmula e explicação do $. Metade: descreve a regra sem a fórmula ou sem explicar o $. Zero: não usa formatação condicional.'),
      (v_atividade, 7, 2, 'Descreva como criar a validação de dados com lista suspensa para o código do item (onde fica o comando, a opção Permitir e a Fonte) e o tipo de alerta de erro.', 0.3, 'Selecionar a coluna Código da aba Movimentação → guia Dados → Validação de Dados → Permitir: Lista → Fonte: =Cadastro!$A$2:$A$300. Alerta de erro no estilo Parar (ex.: título "Código inexistente"), que impede gravar o código errado.', 'Palavras-chave: Dados; Validação de Dados; Permitir Lista; Fonte =Cadastro!$A$2:$A$300; alerta Parar; lista suspensa. Nota cheia: caminho, Lista, Fonte e alerta Parar. Metade: falta a Fonte ou o alerta. Zero: não descreve validação.'),
      (v_atividade, 7, 3, 'Explique as duas etapas para proteger as fórmulas e ainda deixar os operadores digitarem nas células de entrada.', 0.4, 'Etapa 1: selecionar as células de entrada e, em Formatar Células (Ctrl+1) → aba Proteção, desmarcar "Bloqueadas". Etapa 2: guia Revisão → Proteger Planilha (com senha opcional). As fórmulas ficam travadas e as células destravadas continuam editáveis.', 'Palavras-chave: destravar células de entrada; desmarcar Bloqueadas; Formatar Células/Proteção; Revisão; Proteger Planilha; fórmulas travadas. Nota cheia: as duas etapas na ordem certa. Metade: só Proteger Planilha, sem destravar as entradas. Zero: não descreve proteção.'),
      (v_atividade, 8, 1, 'Escreva a fórmula PROCV de B2 que traz a descrição pelo código, e explique o papel do $ na matriz e do último argumento 0.', 0.3, '=PROCV(A2;Cadastro!$A$2:$C$301;2;0). O $ trava a matriz para ela não "andar" ao arrastar (senão os últimos itens dão #N/D); o 0 (FALSO) força a correspondência exata do código.', 'Palavras-chave: PROCV; A2; Cadastro!$A$2:$C$301; coluna 2; 0 = correspondência exata; $ trava a matriz. Nota cheia: fórmula e as duas explicações. Metade: fórmula certa sem explicar, ou com índice/argumento errado. Zero: sem PROCV.'),
      (v_atividade, 8, 2, 'Escreva a mesma busca protegida com SEERRO, mostrando "Código não cadastrado", e cite duas causas comuns do erro #N/D.', 0.3, '=SEERRO(PROCV(A2;Cadastro!$A$2:$C$301;2;0);"Código não cadastrado"). Causas do #N/D: código com espaço extra (limpar com ARRUMAR), número salvo como texto, código inexistente no cadastro, falta do 0 no último argumento.', 'Palavras-chave: SEERRO envolvendo o PROCV; mensagem entre aspas; espaço extra/ARRUMAR; número como texto; código inexistente. Nota cheia: fórmula com SEERRO e duas causas. Metade: só a fórmula ou só as causas. Zero: nenhum dos dois.'),
      (v_atividade, 8, 3, 'Explique por que o PROCV não resolve a busca da tabela em que a descrição está à esquerda do código e qual combinação de funções resolve (escreva a estrutura da fórmula).', 0.4, 'O PROCV só procura da esquerda para a direita: a coluna do código precisa ser a primeira da matriz, e aqui a descrição está à esquerda. Resolve com ÍNDICE + CORRESP: =ÍNDICE(B:B;CORRESP(código;C:C;0)) — o CORRESP acha a posição do código e o ÍNDICE devolve a descrição dessa posição.', 'Palavras-chave: PROCV só busca para a direita; primeira coluna; ÍNDICE; CORRESP; posição; 0 exato. Nota cheia: limitação do PROCV e estrutura ÍNDICE + CORRESP. Metade: só uma das partes. Zero: nenhuma.'),
      (v_atividade, 9, 1, 'Escreva a fórmula com SE aninhado que mostra "Crítico" quando o saldo for menor que 10, "Atenção" quando for até 30 e "Normal" acima de 30.', 0.3, '=SE(D2<10;"Crítico";SE(D2<=30;"Atenção";"Normal")).', 'Palavras-chave: SE dentro de SE (aninhado); D2<10; D2<=30; "Crítico"; "Atenção"; "Normal". Nota cheia: fórmula certa com as três faixas. Metade: lógica certa com erro de sintaxe ou de limite (< 30). Zero: um único SE com duas saídas.'),
      (v_atividade, 9, 2, 'Escreva a fórmula que conta quantas requisições são da categoria "EPI" e diga qual pergunta essa função responde.', 0.3, '=CONT.SE(C2:C200;"EPI"). Responde "quantas vezes?" (quantas requisições são de EPI).', 'Palavras-chave: CONT.SE; intervalo C2:C200 (ou C:C); critério "EPI" entre aspas; quantas vezes; contagem. Nota cheia: fórmula e a pergunta. Metade: só a fórmula. Zero: usa SOMASE ou outra função.'),
      (v_atividade, 9, 3, 'Escreva a fórmula que soma o valor total gasto com a categoria "Ferramentas", explicando o papel de cada intervalo.', 0.4, '=SOMASE(C2:C200;"Ferramentas";E2:E200). C2:C200 é o intervalo do critério (onde procura a categoria), "Ferramentas" é o critério e E2:E200 é o intervalo somado (valores); os dois intervalos precisam ter o mesmo tamanho.', 'Palavras-chave: SOMASE; intervalo do critério C; critério "Ferramentas"; intervalo de soma E; mesmo número de linhas. Nota cheia: fórmula e o papel dos intervalos. Metade: fórmula certa sem explicar, ou intervalos trocados. Zero: usa CONT.SE.'),
      (v_atividade, 10, 1, 'Explique por que a soma dos custos deu zero e por que a taxa virou 1500%, e diga como corrigir cada problema.', 0.3, 'O custo foi digitado com "R$" e virou texto (fica alinhado à esquerda), e o Excel não soma texto; deve-se digitar só o número (1500) e aplicar o formato Moeda/Contábil, que só muda a exibição. A taxa virou 1500% porque o formato Porcentagem multiplica o valor por 100; deve-se digitar 0,15 (ou 15%) e então aplicar o formato.', 'Palavras-chave: texto não soma; alinhado à esquerda; digitar só o número; formato Moeda; formatação não muda o valor; 0,15 ou 15%; % multiplica por 100. Nota cheia: explica e corrige os dois problemas. Metade: só um dos dois. Zero: nenhum.'),
      (v_atividade, 10, 2, 'Escreva a fórmula do vencimento para a linha 2 e explique por que somar números a uma data funciona; diga também como manter a linha de títulos sempre visível.', 0.3, '=B2+30. Funciona porque, para o Excel, toda data é um número sequencial de dias (contados desde 01/01/1900); somar 30 avança 30 dias. Para manter os títulos visíveis: guia Exibir → Congelar Painéis → Congelar Linha Superior (ou Congelar Painéis com o cursor na célula A2).', 'Palavras-chave: =B2+30; data é número de dias; Exibir; Congelar Painéis; Congelar Linha Superior. Nota cheia: fórmula, explicação e congelamento. Metade: dois dos três. Zero: um ou nenhum.'),
      (v_atividade, 10, 3, 'Descreva como usar o AutoFiltro para mostrar só os itens com custo em estoque maior que R$ 1.000, do maior para o menor, e diga o que acontece com as linhas que não aparecem.', 0.4, 'Ativar o AutoFiltro (Dados → Filtro ou Ctrl+Shift+L), abrir a seta da coluna Custo em Estoque → Filtros de Número → É Maior do que → 1000; depois classificar do Maior para o Menor. As linhas que não atendem ficam apenas ocultas, não são apagadas: ao limpar o filtro, elas voltam.', 'Palavras-chave: AutoFiltro; Ctrl+Shift+L; Filtros de Número; maior que 1.000; classificar do maior para o menor (Z-A); linhas ocultas, não apagadas. Nota cheia: filtro, ordenação e o que acontece com as linhas. Metade: dois dos três. Zero: um ou nenhum.');
end $$;
